import{_ as a,o as i,c as e,a2 as t}from"./chunks/framework.DnrXFDHb.js";const c=JSON.parse('{"title":"训练、微调与对齐","description":"","frontmatter":{},"headers":[],"relativePath":"llm/training-alignment.md","filePath":"llm/training-alignment.md","lastUpdated":1786350421000}'),r={name:"llm/training-alignment.md"};function n(o,l,h,p,d,s){return i(),e("div",null,[...l[0]||(l[0]=[t('<h1 id="训练、微调与对齐" tabindex="-1">训练、微调与对齐 <a class="header-anchor" href="#训练、微调与对齐" aria-label="Permalink to &quot;训练、微调与对齐&quot;">​</a></h1><p>一句话：预训练让模型获得通用语言能力，微调让模型适应任务，对齐让模型更符合人类期望和安全边界。</p><h2 id="预训练" tabindex="-1">预训练 <a class="header-anchor" href="#预训练" aria-label="Permalink to &quot;预训练&quot;">​</a></h2><p>预训练通常使用大规模文本、代码或多模态数据。常见目标是预测下一个 token。</p><p>预训练阶段决定了很多基础能力：</p><ul><li>语言表达。</li><li>常识和知识关联。</li><li>代码结构。</li><li>多语言能力。</li><li>基础推理模式。</li></ul><p>但预训练后的模型不一定会很好地遵循用户指令，也不一定知道如何拒绝不合适请求。</p><h2 id="指令微调" tabindex="-1">指令微调 <a class="header-anchor" href="#指令微调" aria-label="Permalink to &quot;指令微调&quot;">​</a></h2><p>指令微调使用“指令-回答”格式的数据，让模型学会按任务要求输出。</p><p>它会改善：</p><ul><li>回答问题。</li><li>遵守格式。</li><li>分步骤解释。</li><li>改写和总结。</li><li>根据上下文完成任务。</li></ul><p>指令微调不是把知识完整塞进模型。它更多是在调整模型如何使用已有能力。</p><h2 id="对齐" tabindex="-1">对齐 <a class="header-anchor" href="#对齐" aria-label="Permalink to &quot;对齐&quot;">​</a></h2><p>对齐的目标是让模型输出更符合人类偏好，包括有帮助、诚实、安全、清晰。</p><p>常见方向：</p><ul><li>避免明显有害内容。</li><li>遇到不确定时说明限制。</li><li>减少编造引用。</li><li>遵守开发者和系统约束。</li><li>更稳定地执行格式要求。</li></ul><p>对齐会影响模型“愿意回答什么”和“怎么回答”，但不能替代事实验证。</p><h2 id="微调和-rag-的区别" tabindex="-1">微调和 RAG 的区别 <a class="header-anchor" href="#微调和-rag-的区别" aria-label="Permalink to &quot;微调和 RAG 的区别&quot;">​</a></h2><p>微调适合改变模型行为或领域表达习惯。RAG 适合让模型使用外部知识库。</p><p>简单判断：</p><ul><li>需要模型掌握固定格式、语气、分类标准：考虑微调。</li><li>需要回答经常变化的文档、制度、产品资料：优先 RAG。</li><li>需要严格引用来源：优先 RAG。</li><li>需要降低幻觉：RAG 加评估比盲目微调更直接。</li></ul><h2 id="评估" tabindex="-1">评估 <a class="header-anchor" href="#评估" aria-label="Permalink to &quot;评估&quot;">​</a></h2><p>没有评估就很难判断模型是否真的变好。</p><p>基础评估可以包括：</p><ul><li>正确率：答案是否符合事实。</li><li>格式稳定性：是否符合要求结构。</li><li>鲁棒性：换一种问法是否仍然正确。</li><li>拒答质量：不该回答时是否正确处理。</li><li>成本和延迟：是否满足实际使用。</li></ul><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ul><li>“微调可以解决所有知识问题”：知识更新和引用通常更适合 RAG。</li><li>“对齐后就不会错”：对齐改善行为，不保证事实零错误。</li><li>“只看单次演示”：模型需要用一组代表性样例评估。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>继续阅读 <a href="/llm/rag-agent">RAG 与 Agent</a>，了解如何把模型与外部知识、工具和受控执行流程连接起来。</p>',29)])])}const m=a(r,[["render",n]]);export{c as __pageData,m as default};
